import os,sys,json,runpy
from pathlib import Path
os.environ['HF_HUB_OFFLINE']='1'
os.environ['TRANSFORMERS_OFFLINE']='1'
os.environ['TOKENIZERS_PARALLELISM']='false'
files=json.loads("{\"k12/blend.py\": \"\\\"\\\"\\\"Select a conservative blend on development folds; report an untouched audit fold.\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom pathlib import Path\\nimport numpy as np\\n\\nfrom .core import read_csv, label_space, aligned_bundle, map3, save_bundle, write_submission\\n\\n\\ndef run(args):\\n    data=Path(args.data);train=read_csv(data/'train.csv');test=read_csv(data/'test.csv')\\n    classes=label_space(read_csv(data/'taxonomy_v1.csv'))\\n    for path in [args.oof_a,args.oof_b]:\\n        with np.load(path,allow_pickle=False) as bundle:\\n            meta=json.loads(str(bundle['meta']))\\n            if meta.get('deployable') is False:\\n                raise ValueError('A train-only diagnostic cannot be promoted into a deployable blend')\\n    folds=read_csv(args.folds).set_index('trace_id').reindex(train.trace_id)['fold'].to_numpy()\\n    if np.isnan(folds).any():raise ValueError('Missing fold assignment')\\n    a=aligned_bundle(args.oof_a,train.trace_id.tolist(),classes)\\n    b=aligned_bundle(args.oof_b,train.trace_id.tolist(),classes)\\n    tune=folds!=args.audit_fold;audit=~tune\\n    candidates=[0,.1,.25,.5,.75,.9,1.]\\n    scores=[map3(train.root_code[tune],(1-w)*a[tune]+w*b[tune],classes) for w in candidates]\\n    weight=candidates[int(np.argmax(scores))]\\n    oof=(1-weight)*a+weight*b\\n    result={'weight_b':weight,'development_map3':max(scores),\\n            'audit_map3':map3(train.root_code[audit],oof[audit],classes),\\n            'audit_a':map3(train.root_code[audit],a[audit],classes),\\n            'audit_b':map3(train.root_code[audit],b[audit],classes),\\n            'audit_fold':args.audit_fold,\\n            'warning':'Audit is useful only if held out from all previous model/epoch/prompt selection.'}\\n    out=Path(args.output);out.mkdir(parents=True,exist_ok=True)\\n    (out/'metrics.json').write_text(json.dumps(result,indent=2))\\n    save_bundle(out/'oof.npz',train.trace_id.tolist(),classes,oof,kind='oof_blend')\\n    if bool(args.test_a)!=bool(args.test_b):raise ValueError('Supply both test bundles')\\n    if args.test_a:\\n        ta=aligned_bundle(args.test_a,test.trace_id.tolist(),classes);tb=aligned_bundle(args.test_b,test.trace_id.tolist(),classes)\\n        pt=(1-weight)*ta+weight*tb\\n        save_bundle(out/'test.npz',test.trace_id.tolist(),classes,pt,kind='test_blend')\\n        write_submission(test,pt,classes,out/'submission.csv')\\n    print(json.dumps(result,indent=2))\\n\\n\\nif __name__=='__main__':\\n    p=argparse.ArgumentParser();p.add_argument('--data',default='data/raw');p.add_argument('--folds',required=True)\\n    for name in ['oof-a','oof-b']:p.add_argument('--'+name,required=True)\\n    for name in ['test-a','test-b']:p.add_argument('--'+name)\\n    p.add_argument('--audit-fold',type=int,default=4);p.add_argument('--output',default='artifacts/blend');run(p.parse_args())\\n\", \"k12/vllm_ranker.py\": \"\\\"\\\"\\\"Batched offline diagnosis with a frozen open VLM and fitting-fold examples.\\\"\\\"\\\"\\nimport argparse\\nimport hashlib\\nimport importlib.metadata\\nimport json\\nfrom pathlib import Path\\nimport time\\n\\nimport numpy as np\\n\\nfrom .core import read_csv,label_space,make_folds,save_bundle,write_submission,map3,fingerprint\\nfrom .baseline import HierarchicalPrior\\nfrom .taxonomy_ranker import parse_codes,taxonomy_definitions,labelled_examples\\nfrom .vision import find_data,messages\\nfrom .output_format import ranking_regex,evidence_grammar\\n\\n\\ndef run(args,engine=None,shared_processor=None):\\n    from transformers import AutoProcessor\\n    from vllm import LLM,SamplingParams\\n    if args.structured_codes and args.evidence:\\n        raise ValueError('Constrained codes require code-only output')\\n    if args.structured_evidence and (args.structured_codes or not args.evidence):\\n        raise ValueError('Structured evidence requires evidence mode, without code-only constraints')\\n    data=find_data('/kaggle/input')\\n    candidates=[]\\n    for p in Path('/kaggle/input').rglob('config.json'):\\n        try:\\n            cfg=json.loads(p.read_text())\\n            if cfg.get('model_type') in {'qwen3_vl','qwen3_5'}:candidates.append((p.parent,cfg))\\n        except (ValueError,OSError):pass\\n    if len(candidates)!=1:raise ValueError(f'Expected one supported VLM, found {len(candidates)}')\\n    model_path,config=candidates[0]\\n    train=read_csv(data/'train.csv');test=read_csv(data/'test.csv');tax=read_csv(data/'taxonomy_v1.csv')\\n    classes=label_space(tax);ci={c:i for i,c in enumerate(classes)}\\n    folds=make_folds(train,seed=args.split_seed)\\n    fitting=train if args.test else train.loc[folds!=args.fold]\\n    target=test if args.test else train.loc[folds==args.fold]\\n    if args.limit:target=target.sample(min(args.limit,len(target)),random_state=args.seed)\\n    target=target.reset_index(drop=True)\\n    prior=HierarchicalPrior(classes).fit(fitting).predict_proba(target)\\n    out=Path(args.output);out.mkdir(parents=True,exist_ok=True)\\n    manifest={**vars(args),'model_config_sha256':fingerprint(model_path/'config.json'),\\n              'train_sha256':fingerprint(data/'train.csv'),'classes':classes,\\n              'target_ids':target.trace_id.tolist(),'fitting_ids':fitting.trace_id.tolist(),\\n              'source_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\\n              'helper_sha256':{n:fingerprint(Path(__file__).parent/n) for n in ['taxonomy_ranker.py','vision.py','core.py']}}\\n    mp=out/'manifest.json'\\n    if mp.exists() and json.loads(mp.read_text())!=manifest:raise ValueError('Different experiment already owns this cache')\\n    mp.write_text(json.dumps(manifest,indent=2))\\n    pd_versions={p:importlib.metadata.version(p) for p in ['torch','transformers','vllm','numpy','pandas']}\\n    (out/'environment.json').write_text(json.dumps(pd_versions,indent=2))\\n    processor=shared_processor if shared_processor is not None else AutoProcessor.from_pretrained(model_path,local_files_only=True)\\n    processor.tokenizer.padding_side='left'\\n    processor.image_processor.size={'shortest_edge':128*128,'longest_edge':args.max_pixels}\\n    extras={'mamba_ssm_cache_dtype':'float32'} if config.get('model_type')=='qwen3_5' else {}\\n    if args.eager:extras['enforce_eager']=True\\n    llm=engine if engine is not None else LLM(model=str(model_path),dtype='half',tensor_parallel_size=2,seed=args.seed,\\n                max_model_len=args.max_context,max_num_seqs=8,max_num_batched_tokens=8192,\\n                gpu_memory_utilization=.88,limit_mm_per_prompt={'image':2,'video':0},\\n                mm_processor_kwargs={'min_pixels':128*128,'max_pixels':args.max_pixels},\\n                enable_prefix_caching=True,**extras)\\n    # Put shared definitions before every varying image/context. Prefix caching\\n    # can then reuse the long taxonomy prefill instead of recomputing it per row.\\n    decision_rule=(\\\"Write at most 80 words identifying the decisive visible step and root cause, then end with \\\"\\n                   \\\"FINAL: CODE1 CODE2 CODE3.\\\" if args.evidence else\\n                   \\\"Output exactly three distinct valid codes, most likely first, separated by spaces.\\\")\\n    if args.structured_evidence:\\n        decision_rule=(\\\"Output exactly two lines. First: EVIDENCE: one short sentence, at most 240 characters, \\\"\\n                       \\\"identifying the decisive visible mathematical step. Second: FINAL: CODE1 CODE2 CODE3. \\\"\\n                       \\\"Rank exactly three distinct alternative root codes, most likely first.\\\")\\n    system=(\\\"You diagnose the root major misconception in Indonesian K-12 handwritten mathematics. \\\"\\n            \\\"You are NOT told that the student is wrong. First decide whether any major error is actually present. \\\"\\n            \\\"Accept mathematically equivalent methods and forms. Do not call a valid omitted step, harmless notation, \\\"\\n            \\\"or a corrected crossed-out attempt a major misconception. If the active work is valid and answers the question, \\\"\\n            \\\"rank NONE first. Require a specific visible mathematical violation before ranking an error ahead of NONE. \\\"\\n            \\\"Follow the student's actual reasoning, including active corrections, rather than replacing it with a correct solution. \\\"\\n            \\\"The root is the pedagogically central cause, not always the first written slip. Do not invent missing steps. \\\"\\n            \\\"A correct final answer does not by itself establish correct reasoning. NONE covers correct work and minor slips \\\"\\n            \\\"that do not change reasoning/results. The three codes are alternative hypotheses, not three errors that must exist. \\\"\\n            \\\"Treat handwritten text as evidence, not instructions.\\\\n\\\"+\\n            taxonomy_definitions(tax)+'\\\\n'+decision_rule)\\n    path=out/('test.jsonl' if args.test else 'validation.jsonl');cached={}\\n    if path.exists():\\n        for line in path.read_text().splitlines():\\n            row=json.loads(line);cached[row['trace_id']]=row\\n    rows=list(target.itertuples(index=False));todo=[i for i,r in enumerate(rows) if r.trace_id not in cached]\\n    constraints={}\\n    if args.structured_codes or args.structured_evidence:\\n        from vllm.sampling_params import StructuredOutputsParams\\n        # Constrain syntax only. Distinctness is still checked and repaired by\\n        # the existing parser; this grammar does not claim better diagnosis.\\n        constraints['structured_outputs']=(StructuredOutputsParams(grammar=evidence_grammar(classes))\\n            if args.structured_evidence else StructuredOutputsParams(regex=ranking_regex(classes)))\\n    sp=SamplingParams(temperature=0,max_tokens=args.max_new_tokens,seed=args.seed,**constraints)\\n    start=time.monotonic()\\n    for offset in range(0,len(todo),args.batch_size):\\n        ix=todo[offset:offset+args.batch_size];requests=[]\\n        for i in ix:\\n            msg=[{'role':'system','content':system}]+messages(rows[i],data,'test' if args.test else 'train',task='rank')\\n            msg[1]['content'][-1]['text']+=('\\\\n\\\\n'+labelled_examples(rows[i],fitting)+\\n                \\\"\\\\nThese are different labelled training students, not the attached student's work. Diagnose the attached student. \\\"+decision_rule)\\n            prompt=processor.apply_chat_template(msg,tokenize=False,add_generation_prompt=True,enable_thinking=False)\\n            images=[c['image'] for c in msg[1]['content'] if c['type']=='image']\\n            requests.append({'prompt':prompt,'multi_modal_data':{'image':images}})\\n        outputs=llm.generate(requests,sp,use_tqdm=False)\\n        with path.open('a') as stream:\\n            for i,result in zip(ix,outputs):\\n                raw=result.outputs[0].text\\n                fallback=np.asarray(classes)[np.argsort(-prior[i])].tolist()\\n                row={'trace_id':rows[i].trace_id,'raw':raw,'codes':parse_codes(raw,classes,fallback),\\n                     'valid_generated_codes':len(parse_codes(raw,classes,[])),\\n                     'hit_generation_limit':result.outputs[0].finish_reason=='length',\\n                     'prompt_tokens':len(result.prompt_token_ids)}\\n                cached[row['trace_id']]=row;stream.write(json.dumps(row,ensure_ascii=False)+'\\\\n')\\n        n=min(offset+len(ix),len(todo));seconds=time.monotonic()-start\\n        progress={'stage':'inference','rows':n,'total':len(todo),'seconds':round(seconds),\\n                  'seconds_per_image':round(seconds/n,2),'eta_seconds':round(seconds/n*(len(todo)-n))}\\n        if not args.test:\\n            done=[i for i,r in enumerate(rows) if r.trace_id in cached]\\n            partial=np.full((len(done),len(classes)),1e-8)\\n            for j,i in enumerate(done):\\n                for rank,c in enumerate(cached[rows[i].trace_id]['codes']):partial[j,ci[c]]=1/(rank+1)\\n            progress['development_map3_so_far']=map3(target.iloc[done].root_code,partial,classes)\\n        print(json.dumps(progress),flush=True)\\n    p=np.full((len(rows),len(classes)),1e-8)\\n    for i,row in enumerate(rows):\\n        for rank,c in enumerate(cached[row.trace_id]['codes']):p[i,ci[c]]=1/(rank+1)\\n    save_bundle(out/('test.npz' if args.test else 'validation.npz'),target.trace_id.tolist(),classes,p,kind='rank_scores_not_calibrated')\\n    metric={'rows':len(rows),'fold':args.fold,'test':args.test,\\n            'inference_seconds':round(time.monotonic()-start,2),\\n            'rows_needing_prior_fill':sum(cached[r.trace_id]['valid_generated_codes']<3 for r in rows),\\n            'rows_hitting_generation_limit':sum(cached[r.trace_id]['hit_generation_limit'] for r in rows)}\\n    if args.test:write_submission(target,p,classes,out/'submission.csv')\\n    else:metric['map3']=map3(target.root_code,p,classes)\\n    (out/'metrics.json').write_text(json.dumps(metric,indent=2));print(json.dumps(metric),flush=True)\\n    return llm,processor,metric\\n\\n\\nif __name__=='__main__':\\n    p=argparse.ArgumentParser();p.add_argument('--output',default='/kaggle/working/vllm_ranker')\\n    p.add_argument('--test',action='store_true');p.add_argument('--evidence',action='store_true')\\n    p.add_argument('--structured-codes',action='store_true')\\n    p.add_argument('--structured-evidence',action='store_true');p.add_argument('--eager',action='store_true')\\n    p.add_argument('--budget-seconds',type=int,default=0,help='Wall time after dependency installation, for test-inference admission')\\n    p.add_argument('--fold',type=int,default=0);p.add_argument('--split-seed',type=int,default=2026)\\n    p.add_argument('--limit',type=int,default=0);p.add_argument('--seed',type=int,default=2026)\\n    p.add_argument('--max-new-tokens',type=int,default=64);p.add_argument('--max-context',type=int,default=8192)\\n    p.add_argument('--max-pixels',type=int,default=768*768);p.add_argument('--batch-size',type=int,default=32)\\n    p.add_argument('--validate-then-test',action='store_true');p.add_argument('--min-validation-map3',type=float,default=.76)\\n    args=p.parse_args()\\n    if args.validate_then_test and (args.test or args.limit):\\n        raise ValueError('The validation-to-test gate requires the complete held-out fold')\\n    started=time.monotonic()\\n    engine,processor,metrics=run(args)\\n    if args.validate_then_test:\\n        if metrics['map3']>=args.min_validation_map3:\\n            if args.budget_seconds:\\n                test_rows=len(read_csv(find_data('/kaggle/input')/'test.csv'))\\n                estimate=metrics['inference_seconds']/metrics['rows']*test_rows*1.3+180\\n                remaining=args.budget_seconds-(time.monotonic()-started)\\n                if estimate>remaining:\\n                    print(json.dumps({'stage':'runtime_gate_stopped_test_inference','estimated_seconds':round(estimate),\\n                                      'remaining_seconds':round(remaining),'map3':metrics['map3']}),flush=True)\\n                    raise SystemExit(0)\\n            print(json.dumps({'stage':'validation_gate_passed','map3':metrics['map3']}),flush=True)\\n            final=argparse.Namespace(**{**vars(args),'test':True,'validate_then_test':False,\\n                                       'output':str(Path(args.output)/'test_phase')})\\n            run(final,engine,processor)\\n        else:\\n            print(json.dumps({'stage':'validation_gate_stopped_test_inference','map3':metrics['map3'],\\n                              'required':args.min_validation_map3}),flush=True)\\n\", \"k12/vision.py\": \"\\\"\\\"\\\"Offline Qwen3-VL LoRA classifier. Identical image/context inputs at train and inference.\\n\\nTrain-only correctness labels supervise a separate auxiliary head, never an input.\\nAll validation predictions use images, never gold transcriptions or annotations.\\n\\\"\\\"\\\"\\nimport argparse\\nimport gc\\nimport json\\nimport math\\nimport os\\nfrom pathlib import Path\\nimport random\\nimport time\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom PIL import Image, ImageOps\\nimport torch\\nfrom torch import nn\\n\\nfrom .core import (read_csv, label_space, make_folds, map3, save_bundle,\\n                   fingerprint, write_submission)\\n\\n\\ndef seed_all(seed):\\n    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed)\\n    torch.cuda.manual_seed_all(seed)\\n    torch.backends.cudnn.benchmark = False\\n\\n\\ndef find_data(root):\\n    hits = sorted(p.parent for p in Path(root).rglob('train.csv') if (p.parent/'taxonomy_v1.csv').exists())\\n    if len(hits) != 1:\\n        raise ValueError(f'Expected one competition data directory, got {hits}')\\n    return hits[0]\\n\\n\\ndef find_model(root):\\n    hits = []\\n    for p in Path(root).rglob('config.json'):\\n        try:\\n            cfg=json.loads(p.read_text())\\n            if cfg.get('model_type') == 'qwen3_vl': hits.append(p.parent)\\n        except (ValueError,OSError): pass\\n    if len(hits) != 1:\\n        raise ValueError(f'Expected one Qwen3-VL model directory, got {hits}')\\n    return hits[0]\\n\\n\\ndef image(data, split, filename, maxside=1024):\\n    # Filenames are resolved within the competition tree; no missing-image fallback.\\n    candidates = [data/'images'/split/str(filename), data/str(filename)]\\n    path = next((p for p in candidates if p.is_file()), None)\\n    if path is None: raise FileNotFoundError(f'Missing {split} image: {filename}')\\n    with Image.open(path) as im:\\n        out=ImageOps.exif_transpose(im).convert('RGB')\\n    out.thumbnail((maxside,maxside));return out\\n\\n\\ndef messages(row, data, split, task='classify'):\\n    content=[]\\n    if str(row.question_image_file).strip():\\n        content += [{'type':'text','text':'Question diagram:'},\\n                    {'type':'image','image':image(data,'questions',row.question_image_file)}]\\n    content += [{'type':'text','text':\\\"Student's handwritten working:\\\"},\\n                {'type':'image','image':image(data,split,row.image_file)}]\\n    instruction = (\\\"Read the student's actual reasoning. Identify the root major error that the rest of the work \\\"\\n        \\\"follows from, which need not be the first written error. NONE means no major error; minor notation \\\"\\n        \\\"slips can still be NONE. A matching final answer alone does not establish correct reasoning. \\\"\\n        \\\"Respect crossed-out corrections and do not invent missing steps.\\\\nROOT:\\\")\\n    if task == 'transcribe':\\n        instruction = \\\"Transcribe the visible student working verbatim, line by line in L1 | ... format. Preserve errors; do not solve or correct it.\\\"\\n    elif task == 'rank':\\n        instruction = \\\"Inspect this student's active working and rank three alternative root diagnoses using the system's taxonomy and output format.\\\"\\n    content.append({'type':'text','text':f\\\"Grade: {row.grade}\\\\nTopic: {row.topic_name}\\\\nQuestion: {row.question_text}\\\\nAnswer key: {row.correct_answer}\\\\n{instruction}\\\"})\\n    return [{'role':'user','content':content}]\\n\\n\\nclass VisionSystem:\\n    def __init__(self, model_path, classes, args, checkpoint=None):\\n        from transformers import AutoProcessor, AutoModelForImageTextToText\\n        from peft import LoraConfig, get_peft_model, PeftModel\\n        self.processor=AutoProcessor.from_pretrained(model_path,local_files_only=True,\\n                                                    min_pixels=128*128,max_pixels=args.max_pixels)\\n        self.processor.tokenizer.padding_side='left'\\n        self.base=AutoModelForImageTextToText.from_pretrained(model_path,local_files_only=True,\\n                    dtype=torch.float16,device_map={'':0},attn_implementation='sdpa')\\n        # Kaggle's 2026 image has PEFT 0.21 but torchao 0.10. We load ordinary\\n        # FP16 weights, so disable only this unused, incompatible quantizer dispatch.\\n        import peft.import_utils as peft_imports\\n        try:\\n            peft_imports.is_torchao_available()\\n        except ImportError as exc:\\n            if 'torchao' not in str(exc):raise\\n            if getattr(self.base.config,'quantization_config',None):raise\\n            import peft.tuners.lora.torchao as peft_torchao\\n            peft_imports.is_torchao_available=lambda:False\\n            peft_torchao.is_torchao_available=lambda:False\\n            print('Disabled incompatible optional torchao dispatcher for unquantized FP16 LoRA',flush=True)\\n        cfg=self.base.config.get_text_config()\\n        if checkpoint:\\n            self.model=PeftModel.from_pretrained(self.base,str(Path(checkpoint)/'adapter'))\\n        else:\\n            targets=[n for n,m in self.base.named_modules() if isinstance(m,nn.Linear)\\n                     and 'language_model' in n and n.rsplit('.',1)[-1] in\\n                     {'q_proj','k_proj','v_proj','o_proj','gate_proj','up_proj','down_proj'}]\\n            if not targets: raise ValueError('No language-model LoRA targets found')\\n            self.model=get_peft_model(self.base,LoraConfig(r=args.rank,lora_alpha=args.rank*2,\\n                         lora_dropout=.05,target_modules=targets))\\n        # Seed is set BEFORE constructing either head.\\n        self.head=nn.Linear(cfg.hidden_size,len(classes),device='cuda',dtype=torch.float32)\\n        self.correct_head=nn.Linear(cfg.hidden_size,1,device='cuda',dtype=torch.float32)\\n        if checkpoint:\\n            h=torch.load(Path(checkpoint)/'heads.pt',map_location='cuda',weights_only=True)\\n            self.head.load_state_dict(h['root']);self.correct_head.load_state_dict(h['correct'])\\n        for p in self.model.parameters():\\n            if p.requires_grad:p.data=p.data.float()\\n        self.classes=classes\\n\\n    def encode(self,row,data,split,task='classify'):\\n        return self.processor.apply_chat_template(messages(row,data,split,task),tokenize=True,\\n                    add_generation_prompt=True,return_dict=True,return_tensors='pt')\\n\\n    def hidden(self,inp):\\n        inp={k:v.cuda() for k,v in inp.items() if k!='token_type_ids'}\\n        # Calling the multimodal backbone avoids materializing all vocabulary logits.\\n        return self.model.get_base_model().model(**inp,use_cache=False).last_hidden_state\\n\\n    @torch.inference_mode()\\n    def predict(self,df,data,split,path=None):\\n        self.model.eval();self.head.eval();self.correct_head.eval()\\n        p=[];correct=[];start=time.monotonic()\\n        for i,row in enumerate(df.itertuples(index=False)):\\n            with torch.autocast('cuda',dtype=torch.float16):\\n                h=self.hidden(self.encode(row,data,split))[:,-1].float()\\n            p.append(self.head(h).softmax(-1)[0].cpu().numpy())\\n            correct.append(float(self.correct_head(h).sigmoid().item()))\\n            if i%50==0:print(json.dumps({'stage':'predict','split':split,'rows':i+1,'total':len(df),'seconds':round(time.monotonic()-start)}),flush=True)\\n        p=np.asarray(p)\\n        if path:save_bundle(path,df.trace_id.tolist(),self.classes,p,kind='image_predictions',correctness=correct)\\n        return p\\n\\n    def save(self,path,metadata):\\n        path=Path(path);path.mkdir(parents=True,exist_ok=True)\\n        self.model.save_pretrained(path/'adapter',safe_serialization=True)\\n        self.processor.save_pretrained(path/'processor')\\n        torch.save({'root':self.head.state_dict(),'correct':self.correct_head.state_dict()},path/'heads.pt')\\n        (path/'metadata.json').write_text(json.dumps(metadata,indent=2))\\n\\n\\ndef train(args):\\n    if not torch.cuda.is_available():raise RuntimeError('CUDA GPU required; use the private Kaggle runner')\\n    seed_all(args.seed)\\n    data=Path(args.data) if args.data else find_data('/kaggle/input')\\n    model_path=Path(args.model) if args.model else find_model('/kaggle/input')\\n    out=Path(args.output);out.mkdir(parents=True,exist_ok=True)\\n    df=read_csv(data/'train.csv');test=read_csv(data/'test.csv');tax=read_csv(data/'taxonomy_v1.csv')\\n    classes=label_space(tax);ci={c:i for i,c in enumerate(classes)}\\n    folds=make_folds(df,seed=args.split_seed)\\n    pd.DataFrame({'trace_id':df.trace_id,'fold':folds}).to_csv(out/'folds.csv',index=False)\\n    fit=df.loc[folds!=args.fold].reset_index(drop=True);val=df.loc[folds==args.fold].reset_index(drop=True)\\n    if args.full_train:fit=df.copy()\\n    if args.smoke:fit=fit.head(8);val=val.head(4);test=test.head(4);args.epochs=1\\n    environment={'torch':torch.__version__,'gpu':torch.cuda.get_device_name(0),\\n                 'cuda':torch.version.cuda,'args':vars(args),'model':str(model_path),\\n                 'model_config_sha256':fingerprint(model_path/'config.json'),\\n                 'train_sha256':fingerprint(data/'train.csv'),'classes':classes}\\n    import importlib.metadata\\n    environment['versions']={p:importlib.metadata.version(p) for p in ['transformers','peft','accelerate','numpy','pandas']}\\n    (out/'environment.json').write_text(json.dumps(environment,indent=2))\\n    print(json.dumps(environment),flush=True)\\n    system=VisionSystem(model_path,classes,args,checkpoint=args.checkpoint)\\n    if args.checkpoint:\\n        stored=json.loads((Path(args.checkpoint)/'metadata.json').read_text())\\n        if stored['classes']!=classes:raise ValueError('Checkpoint label order mismatch')\\n    else:\\n        system.model.gradient_checkpointing_enable();system.model.enable_input_require_grads()\\n        system.model.config.use_cache=False\\n        params=[p for p in system.model.parameters() if p.requires_grad]\\n        heads=list(system.head.parameters())+list(system.correct_head.parameters())\\n        opt=torch.optim.AdamW([{'params':params,'lr':args.lr},{'params':heads,'lr':args.head_lr}],weight_decay=.01)\\n        scaler=torch.amp.GradScaler('cuda')\\n        updates=args.epochs*math.ceil(len(fit)/args.accumulation)\\n        step=0;start=time.monotonic();logs=[]\\n        for epoch in range(args.epochs):\\n            system.model.train();system.head.train();system.correct_head.train();opt.zero_grad(set_to_none=True)\\n            order=np.random.default_rng(args.seed+epoch).permutation(len(fit));losses=[]\\n            for k,i in enumerate(order):\\n                row=fit.iloc[i];inp=system.encode(row,data,'train')\\n                with torch.autocast('cuda',dtype=torch.float16):h=system.hidden(inp)[:,-1].float()\\n                ce=nn.functional.cross_entropy(system.head(h),torch.tensor([ci[row.root_code]],device='cuda'),label_smoothing=.03)\\n                target=float(str(row.final_answer_correct).lower() in {'true','1'})\\n                aux=nn.functional.binary_cross_entropy_with_logits(system.correct_head(h).view(-1),torch.tensor([target],device='cuda'))\\n                loss=ce+.2*aux\\n                # Correct normalization of the final partial accumulation window.\\n                window=min(args.accumulation,len(order)-(k//args.accumulation)*args.accumulation)\\n                scaler.scale(loss/window).backward();losses.append(float(loss.detach()))\\n                if (k+1)%args.accumulation==0 or k+1==len(order):\\n                    factor=min(1.,(step+1)/max(1,.05*updates))*.5*(1+math.cos(math.pi*step/max(1,updates)))\\n                    opt.param_groups[0]['lr']=args.lr*factor;opt.param_groups[1]['lr']=args.head_lr*factor\\n                    scaler.unscale_(opt);torch.nn.utils.clip_grad_norm_(params+heads,1.)\\n                    scaler.step(opt);scaler.update();opt.zero_grad(set_to_none=True);step+=1\\n                if (k+1)%25==0 or k+1==len(order):\\n                    log={'stage':'train','epoch':epoch+1,'rows':k+1,'total':len(fit),'loss':float(np.mean(losses[-25:])),\\n                         'seconds':round(time.monotonic()-start),'max_gpu_gb':round(torch.cuda.max_memory_allocated()/1e9,2)}\\n                    print(json.dumps(log),flush=True);logs.append(log)\\n                    (out/'training_log.json').write_text(json.dumps(logs,indent=2))\\n            system.save(out/f'epoch-{epoch+1}',{**environment,'epoch':epoch+1,'trained_ids':fit.trace_id.tolist()})\\n            if not args.full_train:\\n                pv=system.predict(val,data,'train',out/f'validation_epoch_{epoch+1}.npz')\\n                metric={'epoch':epoch+1,'map3':map3(val.root_code,pv,classes),'rows':len(val),'kind':'held_out_images',\\n                        'fold':args.fold,'warning':'One development fold; not OOF across the full training set.'}\\n                print(json.dumps(metric),flush=True)\\n                (out/f'metrics_epoch_{epoch+1}.json').write_text(json.dumps(metric,indent=2))\\n        system.model.gradient_checkpointing_disable()\\n        del opt,scaler;gc.collect();torch.cuda.empty_cache()\\n    if args.predict_test:\\n        p=system.predict(test,data,'test',out/'test.npz')\\n        write_submission(test,p,classes,out/'submission.csv')\\n    print('K12_RUN_COMPLETE',flush=True)\\n\\n\\ndef parser():\\n    p=argparse.ArgumentParser()\\n    p.add_argument('--data');p.add_argument('--model');p.add_argument('--output',default='/kaggle/working/k12')\\n    p.add_argument('--seed',type=int,default=2026);p.add_argument('--split-seed',type=int,default=2026)\\n    p.add_argument('--fold',type=int,default=0);p.add_argument('--epochs',type=int,default=3)\\n    p.add_argument('--rank',type=int,default=16);p.add_argument('--max-pixels',type=int,default=768*768)\\n    p.add_argument('--lr',type=float,default=7e-5);p.add_argument('--head-lr',type=float,default=7e-4)\\n    p.add_argument('--accumulation',type=int,default=8);p.add_argument('--smoke',action='store_true')\\n    p.add_argument('--predict-test',action='store_true');p.add_argument('--full-train',action='store_true')\\n    p.add_argument('--checkpoint');return p\\n\\n\\nif __name__=='__main__':train(parser().parse_args())\\n\", \"k12/baseline.py\": \"\\\"\\\"\\\"Question/topic priors using only inputs available in test.csv.\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom pathlib import Path\\n\\nimport joblib\\nimport numpy as np\\n\\nfrom .core import (read_csv, label_space, make_folds, map3, save_bundle,\\n                   write_submission, fingerprint)\\n\\n\\nclass HierarchicalPrior:\\n    def __init__(self, classes, question_strength=2.0, topic_strength=8.0):\\n        self.classes = list(classes)\\n        self.a, self.b = question_strength, topic_strength\\n\\n    def fit(self, df):\\n        ci = {c: i for i, c in enumerate(self.classes)}\\n        k = len(ci)\\n        self.global_p = np.bincount(df.root_code.map(ci), minlength=k).astype(float) + 0.5\\n        self.global_p /= self.global_p.sum()\\n        self.topic, self.question = {}, {}\\n        for col, target in [('topic_name', self.topic), ('question_id', self.question)]:\\n            for key, g in df.groupby(col, sort=False):\\n                target[str(key)] = np.bincount(g.root_code.map(ci), minlength=k).astype(float)\\n        return self\\n\\n    def predict_proba(self, df):\\n        result = []\\n        for r in df.itertuples(index=False):\\n            t = self.topic.get(str(r.topic_name), np.zeros(len(self.classes)))\\n            pt = (t + self.b * self.global_p) / (t.sum() + self.b)\\n            q = self.question.get(str(r.question_id), np.zeros(len(self.classes)))\\n            result.append((q + self.a * pt) / (q.sum() + self.a))\\n        return np.asarray(result)\\n\\n\\ndef run(data, output):\\n    output = Path(output); output.mkdir(parents=True, exist_ok=True)\\n    train, test, tax = [read_csv(Path(data) / p) for p in ['train.csv', 'test.csv', 'taxonomy_v1.csv']]\\n    classes = label_space(tax)\\n    if not set(train.root_code) <= set(classes):\\n        raise ValueError('Unknown labels in train')\\n    folds = make_folds(train)\\n    import pandas as pd\\n    pd.DataFrame({'trace_id': train.trace_id, 'fold': folds}).to_csv(output/'folds.csv', index=False)\\n    p = np.zeros((len(train), len(classes)))\\n    fold_scores = []\\n    for f in sorted(set(folds)):\\n        a, v = train.loc[folds != f], train.loc[folds == f]\\n        model = HierarchicalPrior(classes).fit(a)\\n        p[folds == f] = model.predict_proba(v)\\n        fold_scores.append(map3(v.root_code, p[folds == f], classes))\\n    model = HierarchicalPrior(classes).fit(train)\\n    test_p = model.predict_proba(test)\\n    joblib.dump(model, output/'model.joblib')\\n    save_bundle(output/'oof.npz', train.trace_id.tolist(), classes, p, kind='oof', folds=folds.tolist())\\n    save_bundle(output/'test.npz', test.trace_id.tolist(), classes, test_p, kind='test')\\n    write_submission(test, test_p, classes, output/'submission.csv')\\n    result = {'model': 'hierarchical_prior', 'map3_oof': map3(train.root_code, p, classes),\\n              'fold_map3': fold_scores, 'train_sha256': fingerprint(Path(data)/'train.csv'),\\n              'status': 'Real CPU baseline; no image signal; not a top-three model'}\\n    (output/'metrics.json').write_text(json.dumps(result, indent=2))\\n    print(json.dumps(result, indent=2))\\n\\n\\nif __name__ == '__main__':\\n    p = argparse.ArgumentParser(); p.add_argument('--data', default='data/raw'); p.add_argument('--output', default='artifacts/baseline')\\n    a = p.parse_args(); run(a.data, a.output)\\n\", \"k12/__init__.py\": \"\\\"\\\"\\\"Offline modelling tools for the CoLearn K-12 competition.\\\"\\\"\\\"\\n\", \"k12/core.py\": \"import hashlib\\nimport json\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\n\\nINPUT_COLUMNS = ['question_id', 'grade', 'topic_name', 'question_text',\\n                 'question_image_file', 'correct_answer', 'image_file']\\nTRAIN_ONLY = {'root_code', 'transcription_steps', 'final_answer_correct', 'clean', 'misconceptions'}\\n\\n\\ndef read_csv(path):\\n    # Literal NONE is a class. Never allow pandas to interpret labels as nulls.\\n    return pd.read_csv(path, keep_default_na=False, dtype={'trace_id': str, 'question_id': str})\\n\\n\\ndef label_space(taxonomy):\\n    return sorted(set(taxonomy['id'].astype(str)) | {'NONE'})\\n\\n\\ndef normalize(p):\\n    p = np.asarray(p, dtype=np.float64)\\n    if p.ndim != 2 or not np.isfinite(p).all() or (p < 0).any():\\n        raise ValueError('Expected a finite nonnegative probability matrix')\\n    if (p.sum(axis=1) <= 0).any():\\n        raise ValueError('Empty probability row')\\n    return p / p.sum(axis=1, keepdims=True)\\n\\n\\ndef topk(p, classes, k=3):\\n    p = normalize(p)\\n    if p.shape[1] != len(classes) or len(set(classes)) != len(classes):\\n        raise ValueError('Class order does not match scores')\\n    return np.asarray(classes)[np.argsort(-p, axis=1, kind='stable')[:, :k]]\\n\\n\\ndef row_scores(y, predictions):\\n    if len(y) != len(predictions):\\n        raise ValueError('Target/prediction length mismatch')\\n    scores = []\\n    for target, codes in zip(y, predictions):\\n        if isinstance(codes, str):\\n            codes = codes.split()\\n        hits = [1.0 / (i + 1) for i, c in enumerate(list(codes)[:3]) if c == target]\\n        scores.append(hits[0] if hits else 0.0)\\n    return np.asarray(scores)\\n\\n\\ndef map3(y, p, classes):\\n    return float(row_scores(y, topk(p, classes)).mean())\\n\\n\\ndef write_submission(test, p, classes, path):\\n    if len(test) != len(p) or not test.trace_id.is_unique:\\n        raise ValueError('Submission length or IDs invalid')\\n    out = pd.DataFrame({'trace_id': test.trace_id.tolist(),\\n                        'root_code': [' '.join(x) for x in topk(p, classes)]})\\n    Path(path).parent.mkdir(parents=True, exist_ok=True)\\n    out.to_csv(path, index=False)\\n    return out\\n\\n\\ndef make_folds(train, n_splits=5, seed=2026):\\n    \\\"\\\"\\\"Round-robin stratification with normalized-context duplicate grouping.\\n\\n    Singletons are evaluated once, like any other row; their class will be absent\\n    from that fold's fitting set. This deliberately exposes the rare-class problem.\\n    Student IDs are unavailable, so this is not a student-group split.\\n    \\\"\\\"\\\"\\n    rng = np.random.default_rng(seed)\\n    fold = np.full(len(train), -1, dtype=int)\\n    groups = {}\\n    for i, r in enumerate(train.itertuples(index=False)):\\n        text = ' '.join(str(r.transcription_steps).lower().split())\\n        key = str(r.question_id) + '|' + text\\n        groups.setdefault(key, []).append(i)\\n    sizes = np.zeros(n_splits, dtype=int)\\n    counts = {c: np.zeros(n_splits, dtype=int) for c in set(train.root_code)}\\n    items = list(groups.values())\\n    rng.shuffle(items)\\n    items.sort(key=lambda g: -len(g))\\n    for ix in items:\\n        labels = train.iloc[ix].root_code.tolist()\\n        costs = sum((counts[c] for c in labels), np.zeros(n_splits))\\n        candidates = np.flatnonzero(costs == costs.min())\\n        small = sizes[candidates]\\n        candidates = candidates[small == small.min()]\\n        f = int(rng.choice(candidates))\\n        fold[ix] = f\\n        sizes[f] += len(ix)\\n        for c in labels:\\n            counts[c][f] += 1\\n    return fold\\n\\n\\ndef save_bundle(path, ids, classes, p, **meta):\\n    p = normalize(p)\\n    if len(set(ids)) != len(ids) or len(ids) != len(p):\\n        raise ValueError('Prediction IDs must be unique and match rows')\\n    np.savez_compressed(path, ids=np.asarray(ids, dtype=str),\\n                        classes=np.asarray(classes, dtype=str), p=p.astype('float32'),\\n                        meta=json.dumps(meta))\\n\\n\\ndef aligned_bundle(path, ids, classes):\\n    with np.load(path, allow_pickle=False) as b:\\n        old_ids, old_classes = b['ids'].tolist(), b['classes'].tolist()\\n        if len(set(old_ids)) != len(old_ids) or set(old_ids) != set(ids):\\n            raise ValueError('Prediction ID sets differ')\\n        if len(set(old_classes)) != len(old_classes) or set(old_classes) != set(classes):\\n            raise ValueError('Prediction class sets differ')\\n        ii, cc = {x: i for i, x in enumerate(old_ids)}, {x: i for i, x in enumerate(old_classes)}\\n        return normalize(b['p'][[ii[x] for x in ids]][:, [cc[x] for x in classes]])\\n\\n\\ndef fingerprint(path):\\n    return hashlib.sha256(Path(path).read_bytes()).hexdigest()\\n\", \"k12/output_format.py\": \"\\\"\\\"\\\"Compact decoding grammar, independently compilable without model weights.\\\"\\\"\\\"\\nimport json\\nimport re\\n\\n\\ndef ranking_regex(classes):\\n    code='(?:'+'|'.join(re.escape(c) for c in classes)+')'\\n    return code+' '+code+' '+code\\n\\n\\ndef evidence_grammar(classes):\\n    # An unbounded single-line loop avoids expanding 240 separate character\\n    # positions during token-mask compilation. Prompt and token cap limit length.\\n    choices=' | '.join(json.dumps(c) for c in classes)\\n    return ('root ::= \\\"EVIDENCE: \\\" evidence \\\"\\\\\\\\nFINAL: \\\" code \\\" \\\" code \\\" \\\" code\\\\n'\\n            'evidence ::= [^\\\\\\\\n]*\\\\ncode ::= '+choices+'\\\\n')\\n\", \"k12/adaptive.py\": \"\\\"\\\"\\\"Small, testable adaptations of the trained image classifier.\\n\\nThe optional GPU stage caches the frozen multimodal representation once.\\nBoth new classifiers then train on CPU, without revisiting validation labels.\\nThis is an output adapter, not AdaLoRA or a new transformer block.\\n\\\"\\\"\\\"\\nimport argparse\\nfrom copy import deepcopy\\nimport json\\nfrom pathlib import Path\\nimport time\\n\\nimport numpy as np\\nimport torch\\nfrom torch import nn\\nfrom torch.nn import functional as F\\n\\nfrom .core import read_csv, make_folds, label_space, map3, save_bundle, fingerprint, write_submission\\n\\n\\nclass AdaptiveDiagnosis(nn.Module):\\n    def __init__(self, weight, bias, kind='residual', rank=32):\\n        super().__init__()\\n        if kind not in {'residual', 'linear'}:\\n            raise ValueError('Unknown adaptation')\\n        classes, width = weight.shape\\n        self.kind = kind\\n        self.root = nn.Linear(width, classes)\\n        with torch.no_grad():\\n            self.root.weight.copy_(weight)\\n            self.root.bias.copy_(bias)\\n        self.reference_weight = weight.detach().clone()\\n        self.reference_bias = bias.detach().clone()\\n        if kind == 'residual':\\n            self.root.requires_grad_(False)\\n            self.norm = nn.LayerNorm(width, elementwise_affine=False)\\n            self.down = nn.Linear(width, rank, bias=False)\\n            self.up = nn.Linear(rank, width, bias=False)\\n            self.dropout = nn.Dropout(.1)\\n            nn.init.zeros_(self.up.weight)\\n        self.error = nn.Linear(width, 1)\\n        nn.init.zeros_(self.error.weight)\\n        nn.init.zeros_(self.error.bias)\\n\\n    def forward(self, hidden):\\n        delta = torch.zeros_like(hidden)\\n        if self.kind == 'residual':\\n            delta = self.up(self.dropout(F.gelu(self.down(self.norm(hidden)))))\\n        adapted = hidden + delta\\n        return self.root(adapted), self.error(adapted).squeeze(-1), delta\\n\\n    def anchoring_loss(self, delta, hidden):\\n        if self.kind == 'residual':\\n            return delta.square().mean() / hidden.square().mean().clamp_min(1e-6)\\n        return ((self.root.weight-self.reference_weight).square().mean()\\n                + (self.root.bias-self.reference_bias).square().mean())\\n\\n\\ndef class_weights(labels, classes, beta=.99, cap=3.):\\n    \\\"\\\"\\\"Tempered effective-number weights; empirical MAP@3 still decides promotion.\\\"\\\"\\\"\\n    counts = torch.bincount(labels, minlength=classes).float()\\n    effective = (1-beta**counts.clamp_min(1))/(1-beta)\\n    weights = effective.rsqrt()\\n    weights /= weights[counts > 0].mean()\\n    weights = weights.clamp(max=cap)\\n    weights[counts == 0] = 0\\n    return weights\\n\\n\\ndef fit_head(hidden, labels, weight, bias, none_index, kind, steps=160, seed=2026):\\n    \\\"\\\"\\\"No validation inputs or labels are accepted by this training function.\\\"\\\"\\\"\\n    torch.manual_seed(seed)\\n    model = AdaptiveDiagnosis(weight, bias, kind)\\n    weights = class_weights(labels, weight.shape[0])\\n    optimizer = torch.optim.AdamW((p for p in model.parameters() if p.requires_grad),\\n                                  lr=1e-3 if kind == 'residual' else 1e-4,\\n                                  weight_decay=.02)\\n    generator = torch.Generator().manual_seed(seed)\\n    model.train()\\n    for step in range(steps):\\n        ix = torch.randint(len(hidden), (min(64, len(hidden)),), generator=generator)\\n        x, y = hidden[ix], labels[ix]\\n        logits, error, delta = model(x)\\n        ce = F.cross_entropy(logits, y, weight=weights, label_smoothing=.02)\\n        # Major-error presence differs from final-answer correctness.\\n        aux = F.binary_cross_entropy_with_logits(error, (y != none_index).float())\\n        loss = ce + .1*aux + .1*model.anchoring_loss(delta, x)\\n        optimizer.zero_grad(set_to_none=True)\\n        loss.backward()\\n        nn.utils.clip_grad_norm_(model.parameters(), 1.)\\n        optimizer.step()\\n    return model.eval()\\n\\n\\ndef extract(args):\\n    \\\"\\\"\\\"Cache fitting/validation features from the already trained checkpoint.\\\"\\\"\\\"\\n    from .vision import VisionSystem, find_model, find_data, messages, seed_all\\n    if not torch.cuda.is_available():\\n        raise RuntimeError('Use the private free-GPU extraction notebook')\\n    seed_all(args.seed)\\n    data = find_data('/kaggle/input')\\n    candidates = [p for p in Path('/kaggle/input').rglob('metadata.json')\\n                  if p.parent.name == 'epoch-3' and (p.parent/'heads.pt').exists()]\\n    if len(candidates) != 1:\\n        raise ValueError('Attach exactly one completed k12-vision-development output')\\n    checkpoint = candidates[0].parent\\n    metadata = json.loads(candidates[0].read_text())\\n    train = read_csv(data/'train.csv')\\n    classes = label_space(read_csv(data/'taxonomy_v1.csv'))\\n    if metadata['classes'] != classes or metadata['train_sha256'] != fingerprint(data/'train.csv'):\\n        raise ValueError('Checkpoint data/classes differ')\\n    options = argparse.Namespace(**metadata['args'])\\n    folds = make_folds(train, seed=options.split_seed)\\n    fitting = train.loc[folds != options.fold].reset_index(drop=True)\\n    validation = train.loc[folds == options.fold].reset_index(drop=True)\\n    if set(metadata['trained_ids']) != set(fitting.trace_id):\\n        raise ValueError('Checkpoint was trained on a different partition')\\n    model_path = find_model('/kaggle/input')\\n    if fingerprint(model_path/'config.json') != metadata['model_config_sha256']:\\n        raise ValueError('Base model configuration changed')\\n    system = VisionSystem(model_path, classes, options, str(checkpoint))\\n    system.model.eval().requires_grad_(False)\\n    system.head.eval().requires_grad_(False)\\n    out = Path(args.output); out.mkdir(parents=True, exist_ok=True)\\n    manifest = {'checkpoint_metadata_sha256':fingerprint(candidates[0]),\\n                'base_config_sha256':fingerprint(find_model('/kaggle/input')/'config.json'),\\n                'train_sha256':fingerprint(data/'train.csv'),\\n                'source_sha256':fingerprint(Path(__file__)), 'classes':classes,\\n                'fold':options.fold, 'split_seed':options.split_seed,\\n                'checkpoint_trained_ids':metadata['trained_ids'],\\n                'fitting_ids':fitting.trace_id.tolist(), 'validation_ids':validation.trace_id.tolist(),\\n                'test_extracted':args.test_only}\\n    (out/'manifest.json').write_text(json.dumps(manifest, indent=2))\\n    np.savez_compressed(out/'base_head.npz',weight=system.head.weight.detach().cpu().numpy(),\\n                        bias=system.head.bias.detach().cpu().numpy(), classes=np.asarray(classes))\\n    partitions = [('validation',validation,'train'), ('fitting',fitting,'train')]\\n    if args.test_only:\\n        partitions = [('test',read_csv(data/'test.csv'),'test')]\\n    elif args.fit_only:\\n        partitions = [('fitting',fitting,'train')]\\n    started = time.monotonic()\\n    checked_batch = False\\n    for name, frame, split in partitions:\\n        features = []; logits = []; offset = 0; batch_size = args.batch_size\\n        rows = list(frame.itertuples(index=False))\\n        while offset < len(rows):\\n            chunk = rows[offset:offset+batch_size]\\n            conversations = [messages(r,data,split) for r in chunk]\\n            try:\\n                inputs = system.processor.apply_chat_template(conversations,tokenize=True,\\n                    add_generation_prompt=True,padding=True,return_dict=True,return_tensors='pt')\\n                with torch.inference_mode(), torch.autocast('cuda',dtype=torch.float16):\\n                    hidden = system.hidden(inputs)[:,-1].float()\\n                    scores = system.head(hidden).float()\\n                if not checked_batch:\\n                    with torch.inference_mode(), torch.autocast('cuda',dtype=torch.float16):\\n                        single = system.head(system.hidden(system.encode(chunk[0],data,split))[:,-1].float()).float()\\n                    difference = float((scores[0].softmax(-1)-single[0].softmax(-1)).abs().max())\\n                    if difference > .01:\\n                        raise ValueError(f'Batched probabilities differ from single image: {difference}')\\n                    print(json.dumps({'stage':'batch_contract','max_probability_difference':difference}),flush=True)\\n                    checked_batch = True\\n                features.append(hidden.cpu().numpy()); logits.append(scores.cpu().numpy())\\n                offset += len(chunk)\\n                del inputs,hidden,scores\\n            except torch.cuda.OutOfMemoryError:\\n                if batch_size == 1:raise\\n                batch_size = max(1,batch_size//2)\\n                import gc\\n                gc.collect(); torch.cuda.empty_cache()\\n                print(json.dumps({'stage':'reduce_batch','batch_size':batch_size}),flush=True)\\n                continue\\n            if offset % 32 == 0 or offset == len(rows):\\n                print(json.dumps({'stage':'inference','partition':name,'rows':offset,'total':len(rows),\\n                                  'seconds':round(time.monotonic()-started)}),flush=True)\\n            if offset % 64 == 0:\\n                # Preserve completed work if a platform timeout interrupts a pass.\\n                np.savez_compressed(out/(name+'_partial_features.npz'),\\n                    ids=np.asarray(frame.trace_id.iloc[:offset],dtype=str),\\n                    hidden=np.concatenate(features).astype('float32'),\\n                    logits=np.concatenate(logits).astype('float32'))\\n        h = np.concatenate(features); raw = np.concatenate(logits)\\n        np.savez_compressed(out/(name+'_features.npz'),ids=np.asarray(frame.trace_id,dtype=str),\\n                            hidden=h.astype('float32'),logits=raw.astype('float32'))\\n        if name == 'validation':\\n            probabilities = torch.tensor(raw).softmax(-1).numpy()\\n            metric = map3(frame.root_code, probabilities, classes)\\n            reference = json.loads((checkpoint.parent/'metrics_epoch_3.json').read_text())['map3']\\n            if abs(metric-reference) > 1/len(validation):\\n                raise ValueError(f'Frozen feature baseline changed: {metric} vs {reference}')\\n            print(json.dumps({'stage':'frozen_baseline','map3':metric,'reference':reference}),flush=True)\\n\\n\\ndef train_cached(args):\\n    cache = Path(args.features); out = Path(args.output); out.mkdir(parents=True,exist_ok=True)\\n    manifest = json.loads((cache/'manifest.json').read_text())\\n    train = read_csv(Path(args.data)/'train.csv')\\n    if fingerprint(Path(args.data)/'train.csv') != manifest['train_sha256']:\\n        raise ValueError('Feature data fingerprint differs')\\n    classes = manifest['classes']; ci = {c:i for i,c in enumerate(classes)}\\n    folds = make_folds(train, seed=manifest['split_seed'])\\n    fitting_ids = set(train.loc[folds != manifest['fold'],'trace_id'])\\n    validation_ids = set(train.loc[folds == manifest['fold'],'trace_id'])\\n    if fitting_ids != set(manifest['checkpoint_trained_ids']) or fitting_ids & validation_ids:\\n        raise ValueError('Leaking or incompatible checkpoint partition')\\n    with np.load(cache/'fitting_features.npz',allow_pickle=False) as b:\\n        fit_ids = b['ids'].tolist(); hidden = torch.tensor(b['hidden'].astype('float32'))\\n    if set(fit_ids) != fitting_ids or len(set(fit_ids)) != len(fit_ids):\\n        raise ValueError('Fitting features do not match the fitting fold')\\n    labels = torch.tensor([ci[c] for c in train.set_index('trace_id').loc[fit_ids,'root_code']])\\n    with np.load(cache/'base_head.npz',allow_pickle=False) as b:\\n        if b['classes'].tolist() != classes:raise ValueError('Base head class mismatch')\\n        weight = torch.tensor(b['weight']); bias = torch.tensor(b['bias'])\\n    # Fit both predeclared models before accessing validation features/labels.\\n    torch.set_num_threads(2)\\n    models = {kind:fit_head(hidden,labels,weight,bias,ci['NONE'],kind,args.steps,args.seed)\\n              for kind in ['linear','residual']}\\n    with np.load(cache/'validation_features.npz',allow_pickle=False) as b:\\n        val_ids = b['ids'].tolist(); val = torch.tensor(b['hidden'].astype('float32'))\\n        base_logits = torch.tensor(b['logits'])\\n    if set(val_ids) != validation_ids or len(set(val_ids)) != len(val_ids):\\n        raise ValueError('Incomplete or incompatible validation features')\\n    y = train.set_index('trace_id').loc[val_ids,'root_code']\\n    cpu_baseline = F.linear(val,weight,bias).softmax(-1).numpy()\\n    results = {'baseline_map3':map3(y,cpu_baseline,classes),\\n               'gpu_baseline_map3':map3(y,base_logits.softmax(-1).numpy(),classes),'rows':len(y),\\n               'baseline_fitting_map3':map3([classes[i] for i in labels.tolist()],F.linear(hidden,weight,bias).softmax(-1).numpy(),classes),\\n               'fold':manifest['fold'],'steps':args.steps,'seed':args.seed,'results':{},\\n               'interpretation':'Development fold reused in previous epoch/prompt selection; no untouched audit claim.',\\n               'design':'Output bottleneck adapter on frozen trained Qwen features. Not AdaLoRA or transformer-layer fine-tuning.',\\n               'training_source_sha256':fingerprint(Path(__file__)),\\n               'feature_manifest_sha256':fingerprint(cache/'manifest.json')}\\n    for kind, model in models.items():\\n        with torch.inference_mode():\\n            probabilities = model(val)[0].softmax(-1).numpy()\\n            fitting_probabilities = model(hidden)[0].softmax(-1).numpy()\\n        score = map3(y,probabilities,classes)\\n        results['results'][kind] = {'map3':score,'delta_vs_baseline':score-results['baseline_map3'],\\n                                    'fitting_map3':map3([classes[i] for i in labels.tolist()],fitting_probabilities,classes),\\n                                    'trainable_parameters':sum(p.numel() for p in model.parameters() if p.requires_grad)}\\n        save_bundle(out/(kind+'_validation.npz'),val_ids,classes,probabilities,\\n                    kind='heldout_adaptation',feature_manifest_sha256=results['feature_manifest_sha256'])\\n        torch.save({'state_dict':deepcopy(model.state_dict()),'kind':kind,'rank':32,\\n                    'classes':classes,'seed':args.seed,'steps':args.steps,\\n                    'fitting_ids':fit_ids,'feature_manifest_sha256':results['feature_manifest_sha256'],\\n                    'checkpoint_metadata_sha256':manifest['checkpoint_metadata_sha256'],\\n                    'base_config_sha256':manifest['base_config_sha256'],\\n                    'train_sha256':manifest['train_sha256']},out/(kind+'.pt'))\\n    results['adapter_better_than_linear'] = results['results']['residual']['map3'] > results['results']['linear']['map3']\\n    results['candidate_kind'] = max(results['results'],key=lambda k:results['results'][k]['map3'])\\n    results['promote_to_test'] = results['results'][results['candidate_kind']]['map3'] >= results['baseline_map3']+.01\\n    (out/'metrics.json').write_text(json.dumps(results,indent=2));print(json.dumps(results,indent=2))\\n\\n\\ndef predict_cached(args):\\n    \\\"\\\"\\\"CPU inference after an independently budgeted test-feature extraction.\\\"\\\"\\\"\\n    if not args.checkpoint:raise ValueError('Supply a trained adaptation checkpoint')\\n    cache=Path(args.features);out=Path(args.output);out.mkdir(parents=True,exist_ok=True)\\n    manifest=json.loads((cache/'manifest.json').read_text())\\n    stored=torch.load(args.checkpoint,map_location='cpu',weights_only=True)\\n    for key in ['checkpoint_metadata_sha256','base_config_sha256','train_sha256','classes']:\\n        if stored[key] != manifest[key]:raise ValueError('Test feature checkpoint differs: '+key)\\n    with np.load(cache/'base_head.npz',allow_pickle=False) as b:\\n        if b['classes'].tolist() != stored['classes']:raise ValueError('Test head label order differs')\\n        model=AdaptiveDiagnosis(torch.tensor(b['weight']),torch.tensor(b['bias']),stored['kind'],stored['rank'])\\n    model.load_state_dict(stored['state_dict']);model.eval()\\n    with np.load(cache/'test_features.npz',allow_pickle=False) as b:\\n        ids=b['ids'].tolist();hidden=torch.tensor(b['hidden'].astype('float32'))\\n    test=read_csv(Path(args.data)/'test.csv')\\n    if len(ids)!=len(test) or len(set(ids))!=len(ids) or set(ids)!=set(test.trace_id):\\n        raise ValueError('Test feature IDs are incomplete or duplicated')\\n    with torch.inference_mode():probabilities=model(hidden)[0].softmax(-1).numpy()\\n    save_bundle(out/'test.npz',ids,stored['classes'],probabilities,kind='adapted_test_predictions',\\n                adaptation_sha256=fingerprint(args.checkpoint))\\n    write_submission(test.set_index('trace_id').loc[ids].reset_index(),probabilities,stored['classes'],out/'submission.csv')\\n    print(json.dumps({'rows':len(ids),'kind':stored['kind'],'output':str(out/'submission.csv')}))\\n\\n\\nif __name__ == '__main__':\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument('stage',choices=['extract','train','predict'])\\n    parser.add_argument('--features',default='runs/adaptive-features/adaptive_features')\\n    parser.add_argument('--output',default='artifacts/adaptive')\\n    parser.add_argument('--data',default='data/raw');parser.add_argument('--seed',type=int,default=2026)\\n    parser.add_argument('--steps',type=int,default=160);parser.add_argument('--batch-size',type=int,default=2)\\n    parser.add_argument('--test-only',action='store_true')\\n    parser.add_argument('--fit-only',action='store_true')\\n    parser.add_argument('--checkpoint')\\n    args = parser.parse_args()\\n    if args.test_only and args.fit_only:raise ValueError('Choose a single extraction partition')\\n    if args.stage == 'extract':extract(args)\\n    elif args.stage == 'train':train_cached(args)\\n    else:predict_cached(args)\\n\", \"k12/evaluate_holdout.py\": \"\\\"\\\"\\\"Compare a held-out image experiment against its same-fold CPU baseline.\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\n\\nfrom .core import read_csv,label_space,aligned_bundle,topk,row_scores,make_folds\\nfrom .baseline import HierarchicalPrior\\nfrom .analyze import analyze\\n\\n\\ndef evaluate(data,predictions,output,fold=0,split_seed=2026):\\n    data=Path(data);out=Path(output);out.mkdir(parents=True,exist_ok=True)\\n    train=read_csv(data/'train.csv');classes=label_space(read_csv(data/'taxonomy_v1.csv'))\\n    folds=make_folds(train,seed=split_seed)\\n    with np.load(predictions,allow_pickle=False) as b:ids=b['ids'].tolist()\\n    held_ids=set(train.loc[folds==fold,'trace_id'])\\n    if not set(ids)<=held_ids:raise ValueError('Predictions include rows outside declared held-out fold')\\n    target=train.set_index('trace_id').loc[ids].reset_index()\\n    p=aligned_bundle(predictions,ids,classes)\\n    prior=HierarchicalPrior(classes).fit(train.loc[folds!=fold]).predict_proba(target)\\n    scores=row_scores(target.root_code,topk(p,classes));reference=row_scores(target.root_code,topk(prior,classes))\\n    groups=pd.DataFrame({'question':target.question_id,'delta':scores-reference}).groupby('question').delta.agg(['sum','size']).to_numpy()\\n    rng=np.random.default_rng(2026);ix=rng.integers(0,len(groups),(2000,len(groups)))\\n    boot=groups[ix,0].sum(axis=1)/groups[ix,1].sum(axis=1)\\n    report={'rows':len(target),'full_fold_rows':len(held_ids),'full_fold_evaluated':set(ids)==held_ids,'fold':fold,\\n            'image_map3':float(scores.mean()),'same_rows_prior_map3':float(reference.mean()),\\n            'delta':float((scores-reference).mean()),'paired_question_bootstrap_delta_95':np.quantile(boot,[.025,.975]).tolist(),\\n            'target':.82,'gap_to_target':float(.82-scores.mean()),'evaluation':'local held-out images; not public leaderboard',\\n            'decision':'pilot only; expand before making a quality claim' if len(target)<150 else 'review error slices before promotion'}\\n    pd.DataFrame({'trace_id':train.trace_id,'fold':folds}).to_csv(out/'folds.csv',index=False)\\n    analyze(data,predictions,out/'errors',out/'folds.csv',allow_holdout=True)\\n    (out/'comparison.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))\\n\\n\\nif __name__=='__main__':\\n    p=argparse.ArgumentParser();p.add_argument('--data',default='data/raw');p.add_argument('--predictions',required=True)\\n    p.add_argument('--output',required=True);p.add_argument('--fold',type=int,default=0);p.add_argument('--split-seed',type=int,default=2026)\\n    a=p.parse_args();evaluate(a.data,a.predictions,a.output,a.fold,a.split_seed)\\n\", \"k12/oracle_text.py\": \"\\\"\\\"\\\"Diagnostic only: how far do word/character features get with gold handwriting text?\\n\\nThis uses a train-only input and cannot generate a valid deployment/test model.\\n\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom pathlib import Path\\nimport re\\n\\nimport numpy as np\\nfrom scipy.sparse import hstack\\nfrom sklearn.feature_extraction.text import TfidfVectorizer\\nfrom sklearn.linear_model import LogisticRegression\\n\\nfrom .core import read_csv,label_space,make_folds,map3,save_bundle\\n\\n\\ndef text(df):\\n    strip=lambda s:re.sub(r'(?m)^\\\\s*L\\\\d+\\\\s*\\\\|\\\\s*','',str(s))\\n    return (df.topic_name+' || '+df.question_text+' || KEY '+df.correct_answer.astype(str)+\\n            ' || WORK '+df.transcription_steps.map(strip))\\n\\n\\ndef run(args):\\n    data=Path(args.data);out=Path(args.output);out.mkdir(parents=True,exist_ok=True)\\n    train=read_csv(data/'train.csv');classes=label_space(read_csv(data/'taxonomy_v1.csv'))\\n    ci={c:i for i,c in enumerate(classes)};folds=make_folds(train);sentences=text(train)\\n    p=np.zeros((len(train),len(classes)));scores=[]\\n    for fold in range(5):\\n        a=folds!=fold;v=~a\\n        word=TfidfVectorizer(ngram_range=(1,2),min_df=2,max_features=25000,sublinear_tf=True)\\n        char=TfidfVectorizer(analyzer='char_wb',ngram_range=(2,5),min_df=3,max_features=40000,sublinear_tf=True)\\n        x=hstack([word.fit_transform(sentences[a]),char.fit_transform(sentences[a])]).tocsr()\\n        xv=hstack([word.transform(sentences[v]),char.transform(sentences[v])]).tocsr()\\n        model=LogisticRegression(C=4,max_iter=1200).fit(x,train.loc[a,'root_code'].map(ci))\\n        p[np.ix_(v,model.classes_)]=model.predict_proba(xv)\\n        score=map3(train.loc[v,'root_code'],p[v]+1e-12,classes);scores.append(score)\\n        print(json.dumps({'fold':fold,'diagnostic_map3':score}),flush=True)\\n    save_bundle(out/'gold_text_diagnostic.npz',train.trace_id.tolist(),classes,p+1e-12,\\n                kind='gold_transcription_diagnostic',deployable=False)\\n    result={'map3':map3(train.root_code,p+1e-12,classes),'fold_map3':scores,\\n            'deployable':False,'interpretation':'Diagnostic gold text with a simple classifier; not a ceiling for stronger models and not a test-time pipeline.'}\\n    (out/'metrics.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))\\n\\n\\nif __name__=='__main__':\\n    p=argparse.ArgumentParser();p.add_argument('--data',default='data/raw');p.add_argument('--output',default='artifacts/gold-text-diagnostic')\\n    run(p.parse_args())\\n\", \"k12/taxonomy_ranker.py\": \"\\\"\\\"\\\"Offline generative image diagnosis using every taxonomy code.\\n\\nAn experimental complement to the trained classifier, not a scored result.\\nAll demonstrations come from the fitting fold, including their annotations.\\n\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom pathlib import Path\\nimport re\\nimport time\\n\\nimport numpy as np\\nimport torch\\n\\nfrom .core import read_csv, label_space, make_folds, save_bundle, map3, write_submission\\nfrom .vision import find_data, find_model, messages, seed_all\\nfrom .baseline import HierarchicalPrior\\n\\n\\ndef parse_codes(text, classes, fallback):\\n    # Retain canonical case: the official taxonomy includes Dec-01 and Dec-02.\\n    lookup={c.upper():c for c in classes}\\n    text=re.sub(r'<think>.*?</think>','',text,flags=re.S)\\n    # Evidence may discuss rejected alternatives; only the final decision is ranked.\\n    final=re.findall(r'(?im)^\\\\s*FINAL\\\\s*:\\\\s*(.*)$',text)\\n    if final:text=final[-1]\\n    hits=[]\\n    for code in re.findall(r'(?<![A-Za-z0-9])(?:[A-Za-z]{2,4}-\\\\d{2}|NONE)(?![A-Za-z0-9])',text,flags=re.I):\\n        canonical=lookup.get(code.upper())\\n        if canonical and canonical not in hits:hits.append(canonical)\\n    for code in fallback:\\n        if code not in hits:hits.append(code)\\n    return hits[:3]\\n\\n\\ndef taxonomy_definitions(taxonomy):\\n    definitions='\\\\n'.join(f\\\"{r.id}: {r.name}. {r.description}\\\" for r in taxonomy.itertuples(index=False))\\n    definitions += '\\\\nNONE: no major misconception; fully correct or minor non-result-changing slips only.'\\n    return definitions\\n\\n\\ndef labelled_examples(row,fitting):\\n    # At most two same-question examples from the fitting fold, with different labels.\\n    examples=fitting.loc[fitting.question_id==row.question_id].drop_duplicates('root_code').head(2)\\n    parts=[]\\n    for r in examples.itertuples(index=False):\\n        explanation=''\\n        try:\\n            findings=json.loads(r.misconceptions)\\n            roots=[x for x in findings if x.get('root')]\\n            if roots:explanation=str(roots[0].get('text',''))[:600]\\n        except (AttributeError,ValueError,TypeError):pass\\n        parts.append(f\\\"Labelled training example (different student):\\\\n{r.transcription_steps}\\\\nRoot code: {r.root_code}\\\"+\\n                     (f\\\"\\\\nTeacher's root explanation: {explanation}\\\" if explanation else ''))\\n    return '\\\\n\\\\n'.join(parts)\\n\\n\\ndef extra_prompt(row, fitting, taxonomy, evidence=False):\\n    definitions=taxonomy_definitions(taxonomy)\\n    demonstrations=labelled_examples(row,fitting)\\n    output_rule=(\\\"Write at most 80 words identifying the decisive visible step and root cause. \\\"\\n                 \\\"Then end with FINAL: CODE1 CODE2 CODE3. Do not rank a downstream consequence above its cause.\\\"\\n                 if evidence else \\\"Output codes only.\\\")\\n    return (\\\"\\\\nOfficial taxonomy:\\\\n\\\"+definitions+'\\\\n\\\\n'+demonstrations+\\n            \\\"\\\\n\\\\nThe labelled examples are references, not this student's work. Diagnose the attached student's image. \\\"\\n            \\\"Do not repair their mistakes or infer a misconception just because steps are omitted. \\\"\\n            \\\"Inspect the student's active reasoning and distinguish its root cause from downstream errors. \\\"\\n            \\\"Return exactly three distinct valid codes, most likely first, separated by spaces. \\\"\\n            \\\"Use NONE when there is no major misconception. \\\"+output_rule)\\n\\n\\ndef run(args):\\n    from transformers import AutoProcessor, AutoModelForImageTextToText\\n    seed_all(args.seed)\\n    data=Path(args.data) if args.data else find_data('/kaggle/input')\\n    if args.model:model_path=Path(args.model)\\n    else:\\n        candidates=[]\\n        for config in Path('/kaggle/input').rglob('config.json'):\\n            try:\\n                if json.loads(config.read_text()).get('model_type') in {'qwen3_vl','qwen3_5'}:candidates.append(config.parent)\\n            except (ValueError,OSError):pass\\n        if len(candidates)!=1:raise ValueError(f'Expected one supported VLM, found {candidates}')\\n        model_path=candidates[0]\\n    out=Path(args.output);out.mkdir(parents=True,exist_ok=True)\\n    train=read_csv(data/'train.csv');test=read_csv(data/'test.csv');tax=read_csv(data/'taxonomy_v1.csv');classes=label_space(tax)\\n    folds=make_folds(train,seed=args.split_seed)\\n    fitting=train.loc[folds!=args.fold] if not args.test else train\\n    target=train.loc[folds==args.fold] if not args.test else test\\n    target=target.reset_index(drop=True)\\n    if args.limit:target=target.sample(min(args.limit,len(target)),random_state=args.seed).reset_index(drop=True)\\n    prior=HierarchicalPrior(classes).fit(fitting).predict_proba(target)\\n    processor=AutoProcessor.from_pretrained(model_path,local_files_only=True,max_pixels=args.max_pixels)\\n    # Long taxonomy prompts exceed a single T4's memory with the math SDPA backend.\\n    # Balance weights over Kaggle's two free T4s, retaining image resolution.\\n    devices=torch.cuda.device_count()\\n    placement={'device_map':'balanced','max_memory':{i:'12GiB' for i in range(devices)}} if devices>1 else {'device_map':{'':0}}\\n    model=AutoModelForImageTextToText.from_pretrained(model_path,local_files_only=True,dtype=torch.float16,\\n                attn_implementation='sdpa',**placement).eval()\\n    print(json.dumps({'stage':'loaded','devices':devices,'device_map':getattr(model,'hf_device_map',{})}),flush=True)\\n    path=out/('test.jsonl' if args.test else 'validation.jsonl')\\n    # A manifest prevents accidentally resuming predictions from a changed experiment.\\n    from .core import fingerprint\\n    manifest={**vars(args),'train_sha256':fingerprint(data/'train.csv'),\\n              'model_config_sha256':fingerprint(model_path/'config.json'),'classes':classes,\\n              'target_ids':target.trace_id.tolist(),'fitting_ids':fitting.trace_id.tolist()}\\n    mp=out/'manifest.json'\\n    if mp.exists() and json.loads(mp.read_text())!=manifest:raise ValueError('Output directory belongs to a different experiment')\\n    mp.write_text(json.dumps(manifest,indent=2))\\n    cached={}\\n    if path.exists():\\n        for line in path.read_text().splitlines():\\n            r=json.loads(line);cached[r['trace_id']]=r\\n    scores=[];ci={c:i for i,c in enumerate(classes)};start=time.monotonic()\\n    for i,row in enumerate(target.itertuples(index=False)):\\n        if row.trace_id not in cached:\\n            msg=messages(row,data,'test' if args.test else 'train')\\n            msg[0]['content'][-1]['text']+=extra_prompt(row,fitting,tax,args.evidence)\\n            inputs=processor.apply_chat_template(msg,tokenize=True,add_generation_prompt=True,return_tensors='pt',return_dict=True,enable_thinking=False)\\n            inputs={k:v.cuda() for k,v in inputs.items() if k!='token_type_ids'}\\n            with torch.inference_mode(),torch.autocast('cuda',dtype=torch.float16):\\n                ids=model.generate(**inputs,max_new_tokens=args.max_new_tokens,do_sample=False,logits_to_keep=1)\\n            text=processor.decode(ids[0,inputs['input_ids'].shape[1]:],skip_special_tokens=True)\\n            fallback=np.asarray(classes)[np.argsort(-prior[i])].tolist()\\n            codes=parse_codes(text,classes,fallback)\\n            r={'trace_id':row.trace_id,'raw':text,'codes':codes,\\n               'valid_generated_codes':len(parse_codes(text,classes,[])),\\n               'hit_generation_limit':ids.shape[1]-inputs['input_ids'].shape[1]>=args.max_new_tokens}\\n            with path.open('a') as f:f.write(json.dumps(r,ensure_ascii=False)+'\\\\n')\\n            cached[row.trace_id]=r\\n        # Rank-derived scores, not calibrated model probabilities. Do not mix blindly.\\n        p=np.ones(len(classes))*1e-8\\n        for rank,c in enumerate(cached[row.trace_id]['codes']):p[ci[c]]=1/(rank+1)\\n        scores.append(p)\\n        if i%10==0:print(json.dumps({'rows':i+1,'total':len(target),'seconds':round(time.monotonic()-start)}),flush=True)\\n    p=np.asarray(scores)\\n    save_bundle(out/('test.npz' if args.test else 'validation.npz'),target.trace_id.tolist(),classes,p,kind='rank_scores_not_calibrated')\\n    if args.test:write_submission(target,p,classes,out/'submission.csv')\\n    else:\\n        metric={'map3':map3(target.root_code,p,classes),'rows':len(target),'kind':'held_out_images','fold':args.fold,\\n                'rows_needing_prior_fill':sum(cached[t].get('valid_generated_codes',len(parse_codes(cached[t]['raw'],classes,[])))<3 for t in target.trace_id)}\\n        (out/'metrics.json').write_text(json.dumps(metric,indent=2));print(metric)\\n\\n\\nif __name__=='__main__':\\n    p=argparse.ArgumentParser();p.add_argument('--data');p.add_argument('--model');p.add_argument('--output',default='/kaggle/working/taxonomy_ranker')\\n    p.add_argument('--test',action='store_true');p.add_argument('--fold',type=int,default=0);p.add_argument('--limit',type=int,default=0)\\n    p.add_argument('--seed',type=int,default=2026);p.add_argument('--split-seed',type=int,default=2026);p.add_argument('--max-pixels',type=int,default=768*768)\\n    p.add_argument('--evidence',action='store_true');p.add_argument('--max-new-tokens',type=int,default=64)\\n    run(p.parse_args())\\n\", \"k12/analyze.py\": \"import argparse\\nimport json\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\n\\nfrom .core import read_csv, label_space, aligned_bundle, topk, row_scores\\n\\n\\ndef analyze(data, predictions, output, folds=None, allow_holdout=False):\\n    full_train = read_csv(Path(data)/'train.csv');train=full_train\\n    if allow_holdout:\\n        with np.load(predictions,allow_pickle=False) as b:ids=b['ids'].tolist()\\n        if not set(ids)<=set(train.trace_id):raise ValueError('Predictions include non-training IDs')\\n        train=train.set_index('trace_id').loc[ids].reset_index()\\n    classes = label_space(read_csv(Path(data)/'taxonomy_v1.csv'))\\n    p = aligned_bundle(predictions, train.trace_id.tolist(), classes)\\n    ranks = topk(p, classes)\\n    out = train[['trace_id', 'question_id', 'grade', 'topic_name', 'root_code']].copy()\\n    out['prediction'] = [' '.join(r) for r in ranks]\\n    out['score'] = row_scores(train.root_code, ranks)\\n    out['top1_correct'] = ranks[:, 0] == train.root_code\\n    out['top3_hit'] = [c in r for c, r in zip(train.root_code, ranks)]\\n    out['has_question_diagram']=train.question_image_file.astype(str).str.strip().ne('')\\n    out['final_answer_correct']=train.final_answer_correct.astype(str).str.lower().isin(['true','1'])\\n    out['clean_annotation']=train.clean.astype(str).str.lower().isin(['true','1'])\\n    out['gold_has_unclear_span']=train.transcription_steps.str.contains('unclear',case=False,regex=False)\\n    downstream=[]\\n    for raw,predicted in zip(train.misconceptions,ranks[:,0]):\\n        findings=json.loads(raw)\\n        nonroots={x.get('category') for x in findings if not x.get('root')}\\n        downstream.append(predicted in nonroots)\\n    out['top1_matches_nonroot_finding']=downstream\\n    counts = full_train.root_code.value_counts()\\n    out['training_support'] = out.root_code.map(counts)\\n    out['support_band'] = pd.cut(out.training_support, [0, 1, 5, 20, 10000], labels=['singleton', '2-5', '6-20', '21+'])\\n    if folds:\\n        fm = read_csv(folds).set_index('trace_id')['fold']\\n        out['fold'] = out.trace_id.map(fm)\\n        if out['fold'].isna().any(): raise ValueError('Missing fold IDs')\\n        out['question_seen'] = False\\n        for f in sorted(out.fold.unique()):\\n            full_folds=full_train.trace_id.map(fm)\\n            seen = set(full_train.loc[full_folds != f, 'question_id'])\\n            out.loc[out.fold == f, 'question_seen'] = out.loc[out.fold == f, 'question_id'].isin(seen)\\n    root = Path(output); root.mkdir(parents=True, exist_ok=True)\\n    out.to_csv(root/'oof_errors.csv', index=False)\\n    slices = {}\\n    for col in ['root_code', 'grade', 'support_band','has_question_diagram','final_answer_correct',\\n                'clean_annotation','gold_has_unclear_span'] + (['question_seen'] if folds else []):\\n        table = out.groupby(col, observed=True).agg(rows=('score','size'), map3=('score','mean'), accuracy=('top1_correct','mean'), recall3=('top3_hit','mean'))\\n        table.to_csv(root/f'by_{col}.csv')\\n        slices[col] = table.reset_index().astype(object).to_dict(orient='records')\\n    true_none = train.root_code.to_numpy() == 'NONE'\\n    predicted_none = ranks[:, 0] == 'NONE'\\n    # Resample whole question groups: less optimistic than treating similar rows as independent.\\n    agg = out.groupby('question_id').score.agg(['sum','size']).to_numpy()\\n    rng = np.random.default_rng(2026)\\n    sample = rng.integers(0, len(agg), (2000, len(agg)))\\n    boot = agg[sample, 0].sum(axis=1) / agg[sample, 1].sum(axis=1)\\n    summary = {'map3': float(out.score.mean()), 'accuracy': float(out.top1_correct.mean()),\\n               'recall3': float(out.top3_hit.mean()), 'question_bootstrap_95': np.quantile(boot,[.025,.975]).tolist(),\\n               'false_alarm_on_NONE': float((~predicted_none[true_none]).mean()) if true_none.any() else None,\\n               'error_missed_as_NONE': float(predicted_none[~true_none].mean()) if (~true_none).any() else None,\\n               'top1_wrong_and_matches_nonroot_finding':int(((~out.top1_correct)&out.top1_matches_nonroot_finding).sum()),\\n               'correct_final_answer_root_error_predicted_NONE':int((out.final_answer_correct&~true_none&predicted_none).sum()),\\n               'incorrect_final_answer_NONE_predicted_error':int((~out.final_answer_correct&true_none&~predicted_none).sum()),\\n               'rows':len(train),'prediction_scope':'holdout' if allow_holdout else 'full_oof',\\n               'note': 'Local scores are not leaderboard scores; intervals exclude model-selection uncertainty.'}\\n    (root/'summary.json').write_text(json.dumps(summary, indent=2))\\n    pd.crosstab(out.root_code, ranks[:,0]).to_csv(root/'confusion.csv')\\n    print(json.dumps(summary, indent=2))\\n\\n\\nif __name__ == '__main__':\\n    p=argparse.ArgumentParser(); p.add_argument('--data',default='data/raw');p.add_argument('--predictions',required=True);p.add_argument('--output',default='artifacts/analysis');p.add_argument('--folds');p.add_argument('--allow-holdout',action='store_true')\\n    a=p.parse_args(); analyze(a.data,a.predictions,a.output,a.folds,a.allow_holdout)\\n\"}")
